/** Translates address wording and transliterates local place names in the selected script. */
export const localizePlaceText = (value: string, language: Language): string => {
  if (language === 'en') return value;
  const withLocalNames = PLACE_NAMES[language].reduce((text, [pattern, replacement]) => text.replace(pattern, replacement), value);
  return PLACE_WORD_KEYS.reduce((text, [pattern, key]) => text.replace(pattern, uiText(language, key)), withLocalNames);
};

