export const localizeJobTitle = (job: Job, language: Language): string => {
  if (language === 'en') return job.title;
  if (language === 'hi') return job.titleHi;
  return JOB_TITLE_TRANSLATIONS[language]?.[job.id] ?? job.title;
};

