export const localizeTransactionTitle = (id: string, title: string, titleHi: string, language: Language): string => {
  if (language === 'hi') return titleHi;
  if (language === 'en') return title;
  return TRANSACTION_TITLES[language]?.[id] ?? title;
};

const LOCALE_TAG: Record<Language, string> = { en: 'en-IN', hi: 'hi-IN', bn: 'bn-IN', mr: 'mr-IN', te: 'te-IN' };
export const localizeDate = (dateValue: string, language: Language): string => {
  const parsedDate = new Date(dateValue);
  return Number.isNaN(parsedDate.getTime()) ? dateValue : new Intl.DateTimeFormat(LOCALE_TAG[language], { day: 'numeric', month: 'short', year: 'numeric' }).format(parsedDate);
};

